@total_ordering
class Molecule:
    def __init__(self, formula, weight):
        self.formula = formula
        self.weight = weight

    def __eq__(self, other):
        return self.weight == other.weight

    def __lt__(self, other):
        return self.weight < other.weight

from functools import total_ordering

@total_ordering
class Polozka:
    def __init__(self, cena):
        self.cena = cena
    def __eq__(self, jiná):
        return self.cena == jiná.cena
    def __lt__(self, jiná):
        return self.cena < jiná.cena

p1 = Polozka(10)
p2 = Polozka(20)
print(p1 > p2)

memoization.code:
memo = {}

def compute_fibonacci(n):
    try:
        return memo[n]
    except ________:
        if n < 2:
            memo[n] = n
        else:
            memo[n] = compute_fibonacci(n - 1) + compute_fibonacci(n - 2)
        return memo[n]

